// Some portions generated by Co-Pilot
"use client";

import { useTranslations } from "next-intl";
import { Link } from "@/i18n/navigation";
import type { BinaryAssetView } from "@/types/temurin";
import { sendDownloadEvent } from "@/utils/gtag";
import { getExtension, hasInstaller } from "@/utils/temurin";
import { FaWindows, FaApple, FaLinux } from "react-icons/fa";
import { FiDownload } from "react-icons/fi";

interface OneClickDownloadProps {
  selectedVersion: string;
  releases: BinaryAssetView[];
}

const platforms = [
  {
    os: "mac",
    name: "macOS",
    architectures: ["aarch64", "x64"],
    icon: FaApple,
  },
  { os: "windows", name: "Windows", architectures: ["x64"], icon: FaWindows },
  { os: "linux", name: "Linux", architectures: ["x64"], icon: FaLinux },
];

function preferredRelease(
  releases: BinaryAssetView[],
  os: string,
  architectures: string[],
) {
  return releases
    .filter(
      (view) =>
        view.binary?.os === os &&
        architectures.includes(view.binary.architecture ?? "") &&
        Boolean(view.binary.installer?.link || view.binary.package?.link),
    )
    .sort((a, b) => {
      const jdkPreference =
        Number(b.binary?.image_type?.toLowerCase() === "jdk") -
        Number(a.binary?.image_type?.toLowerCase() === "jdk");
      const architecturePreference =
        architectures.indexOf(a.binary?.architecture ?? "") -
        architectures.indexOf(b.binary?.architecture ?? "");
      const installerPreference =
        Number(hasInstaller(b.binary)) - Number(hasInstaller(a.binary));
      return jdkPreference || architecturePreference || installerPreference;
    })[0];
}

const OneClickDownload = ({
  selectedVersion,
  releases,
}: OneClickDownloadProps) => {
  const t = useTranslations("TemurinReleases");
  const downloads = platforms.map((platform) => ({
    ...platform,
    release: preferredRelease(releases, platform.os, platform.architectures),
  }));
  if (!downloads.some((download) => download.release)) return null;

  return (
    <div className="grid gap-3 md:grid-cols-3">
      {downloads.map(({ os, name, icon: Icon, release }) => {
        const binary = release?.binary;
        const artifact = hasInstaller(binary)
          ? binary?.installer
          : binary?.package;
        if (!release || !artifact?.link) return null;
        const link = artifact.link;
        const version = release.release_name ?? selectedVersion;
        const platform =
          os === "mac"
            ? `macOS ${binary?.architecture === "aarch64" ? "Apple Silicon (aarch64)" : "Intel (x64)"}`
            : os === "windows"
              ? "Windows 64 bit"
              : "Linux x64";
        const extension = getExtension(artifact.name).toUpperCase();
        const display = `Temurin ${version}, ${platform}${extension ? ` (.${extension})` : ""}`;
        return (
          <Link
            key={os}
            href={{
              pathname: "/download",
              query: { link, vendor: "Adoptium" },
            }}
            aria-label={t("download-package", { os: name })}
            data-testid={`quick-download-${os}`}
            onClick={() =>
              sendDownloadEvent({
                link,
                os,
                arch: binary?.architecture ?? "x64",
                pkg_type: binary?.image_type ?? "jdk",
                version,
                vendor: "Adoptium",
              })
            }
            className="group grid min-w-0 grid-cols-[auto_1fr_auto] items-center gap-3 rounded-2xl border border-white/10 bg-white/[0.035] p-5 text-white transition-colors hover:border-pink/50 hover:bg-white/5 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
          >
            <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/5">
              <Icon size={22} aria-hidden="true" />
            </span>
            <div className="min-w-0">
              <h3 className="mb-1 text-lg font-semibold">{name}</h3>
              <p className="mb-0 text-xs leading-relaxed text-grey">
                {display}
              </p>
            </div>
            <FiDownload
              size={20}
              className="text-[#ff91b7]"
              aria-hidden="true"
            />
          </Link>
        );
      })}
    </div>
  );
};

export default OneClickDownload;
